// HasDoe applies the HasEdge predicate on the "doe" edge.
func HasDoe() predicate.BreedingRecord {
	return predicate.BreedingRecord(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DoeTable, DoeColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDoeWith applies the HasEdge predicate on the "doe" edge with a given conditions (other predicates).
func HasDoeWith(preds ...predicate.Goat) predicate.BreedingRecord {
	return predicate.BreedingRecord(func(s *sql.Selector) {
		step := newDoeStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BreedingRecord) predicate.BreedingRecord {
	return predicate.BreedingRecord(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BreedingRecord) predicate.BreedingRecord {
	return predicate.BreedingRecord(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BreedingRecord) predicate.BreedingRecord {
	return predicate.BreedingRecord(sql.NotPredicates(p))
}
